#!/usr/bin/env python3
"""Static checks for BAROX VS v027 models, cape solver, config migration and catalogue."""
from __future__ import annotations
import json
import pathlib
import re
import sys

RETIRED = {
    "shoulder_wisp", "pet_sparkles", "butterfly_swarm", "pet_companion",
    "celestial_wings", "jump_crystal", "landing_burst", "sparkle_trail",
    "heart_trail", "bubble_trail", "footsteps", "trail_afterimage", "cape_shimmer",
}


def require(condition: bool, message: str) -> None:
    if not condition:
        raise SystemExit("v027 check failed: " + message)


def main() -> int:
    if len(sys.argv) != 2:
        raise SystemExit("usage: check-v027.py <project-directory>")
    root = pathlib.Path(sys.argv[1])
    def read(relative: str) -> str:
        path = root / relative
        require(path.is_file(), f"missing {relative}")
        return path.read_text(encoding="utf-8")

    catalog = read("src/main/java/com/baroxvs/client/cosmetic/ModuleCatalog.java")
    engine = read("src/main/java/com/baroxvs/client/cosmetic/CosmeticEngine.java")
    cloth = read("src/main/java/com/baroxvs/client/cosmetic/CapeClothSimulation.java")
    config = read("src/main/java/com/baroxvs/client/config/BaroxConfig.java")
    click_gui = read("src/main/java/com/baroxvs/client/gui/ModuleClickGuiScreen.java")
    cloth_gui = read("src/main/java/com/baroxvs/client/gui/BaroxClothConfigScreen.java")

    ids = re.findall(r'(?:toggle|styled|cycle)\("([^"]+)"', catalog)
    require(len(ids) == 78, f"expected 78 active modules, found {len(ids)}")
    require(len(ids) == len(set(ids)), "module IDs are not unique")
    orphan_options = (
        'new String[]{"Crystal Halo", "Sakura Petals", "Butterfly Lift", "Moon Hearts", "Liquid Rings", "Prism Stars"});',
        'new String[]{"Pearl Sprite", "Blue Sprite", "Rose Sprite", "Golden Sprite"});',
        'new String[]{"Aurora", "Moonlight", "Sakura", "Starlight", "Solar Flare", "Prism"});',
    )
    require(not any(line.strip() in orphan_options for line in catalog.splitlines()),
            "orphaned style arrays remain after redundant module removal")
    for retired in RETIRED:
        require(not re.search(r'(?:toggle|styled|cycle)\("' + re.escape(retired) + r'"', catalog),
                f"retired module remains registered: {retired}")
        # Retired identifiers are allowed only in the one-time migration routine.
        require(retired not in engine, f"retired particle/model path still exists: {retired}")

    require("CapeClothSimulation.COLUMNS" in engine and "CapeClothSimulation.ROWS" in engine,
            "cape mesh is not wired to the cloth solver")
    require("capeCloth.update(" in engine and "capeCloth.point(row, col, partial)" in engine,
            "cape tick/render integration missing")
    require("solveStructuralLinks" in cloth and "solveShearLinks" in cloth and "solveBendingLinks" in cloth,
            "cloth constraint solver is incomplete")
    require("keepBehindTorso" in cloth and "renderPrevious" in cloth,
            "cape collision guard or interpolation is missing")
    require("capeCloth" in engine and "capeAccentCell" not in engine and "cape_shimmer" not in engine,
            "legacy sparkle cape surface path remains")

    # Actual cosmetic models must be generated by connected 3D geometry, not Spark emitters.
    for module in ("pet", "wings", "cape", "butterfly_companion"):
        require(f'add("{module}"' not in engine, f"{module} is still emitted as a Spark particle")
    require("drawGlassOrb(out, camera, centre" in engine and "tailRoot" in engine,
            "companion is not a faceted 3D model")
    require("Sculpted shoulder sockets" in engine and "wingPose(root" in engine,
            "wing mounting geometry is missing")

    require('resolve("baran3120.cfg")' in config, "custom config path is missing")
    require('resolve("baroxvs.json")' in config and "Files.copy(LEGACY_FILE, FILE" in config,
            "legacy config migration does not preserve old settings")
    require("migrateV027Modules" in config and 'styleStates.remove("particle_density")' in config,
            "geometry-quality/module migration is missing")
    require('cycle("geometry_quality"' in catalog and 'config.style("geometry_quality")' in cloth_gui,
            "Geometry Detail setting is not connected")
    require("78 MODULES" in click_gui, "GUI count is stale")

    keys = []
    for language in ("en_us", "de_de", "tr_tr"):
        data = json.loads(read(f"src/main/resources/assets/baroxvs/lang/{language}.json"))
        require("baroxvs.module.geometry_quality" in data, f"{language} geometry-quality translation missing")
        require("baroxvs.cloth.geometry_quality" in data, f"{language} Cloth Config translation missing")
        keys.append(set(data.keys()))
    require(keys[0] == keys[1] == keys[2], "language key sets do not match")

    require("BAROX-VS-v027.jar" in read("build.gradle"), "remapped JAR filename not updated")
    require("mod_version=0.27.0" in read("gradle.properties"), "mod version not updated")
    require(read("VERSION").strip() == "BAROX VS v027", "VERSION marker is stale")
    print("v027 static checks passed: 78 modules, custom cloth physics, geometry-only models, config migration, TR/DE/EN translations")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
